--
-- Table structure for table `message`
--

DROP TABLE IF EXISTS `message`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `message` (
  `id` varchar(191) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL,
  `conversationId` varchar(191) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL,
  `senderId` varchar(191) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL,
  `recipientId` varchar(191) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL,
  `escrowId` varchar(191) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `content` text CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL,
  `attachmentUrl` varchar(191) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `attachmentName` varchar(191) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `isRead` tinyint(1) NOT NULL DEFAULT '0',
  `isArchived` tinyint(1) NOT NULL DEFAULT '0',
  `moderationFlagged` tinyint(1) NOT NULL DEFAULT '0',
  `createdAt` datetime(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3),
  `isPinned` tinyint(1) NOT NULL DEFAULT '0',
  `pinnedAt` datetime(3) DEFAULT NULL,
  `pinnedById` varchar(191) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `listingId` varchar(191) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `chatOfferId` varchar(191) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  PRIMARY KEY (`id`),
  KEY `Message_conversationId_createdAt_idx` (`conversationId`,`createdAt`),
  KEY `Message_recipientId_isRead_idx` (`recipientId`,`isRead`),
  KEY `Message_senderId_fkey` (`senderId`),
  KEY `Message_escrowId_isPinned_idx` (`escrowId`,`isPinned`),
  KEY `Message_listingId_fkey` (`listingId`),
  KEY `Message_chatOfferId_idx` (`chatOfferId`),
  CONSTRAINT `Message_chatOfferId_fkey` FOREIGN KEY (`chatOfferId`) REFERENCES `offer` (`id`) ON DELETE SET NULL ON UPDATE CASCADE,
  CONSTRAINT `Message_escrowId_fkey` FOREIGN KEY (`escrowId`) REFERENCES `escrow` (`id`) ON DELETE SET NULL ON UPDATE CASCADE,
  CONSTRAINT `Message_listingId_fkey` FOREIGN KEY (`listingId`) REFERENCES `listing` (`id`) ON DELETE SET NULL ON UPDATE CASCADE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
/*!40101 SET character_set_client = @saved_cs_client */;

