  `email` varchar(191) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL,
  `emailVerified` datetime(3) DEFAULT NULL,
  `password` varchar(191) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `name` varchar(191) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `username` varchar(191) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `image` varchar(191) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `role` enum('USER','ADMIN') CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'USER',
  `kycLevel` enum('NONE','EMAIL','PHONE','ID_VERIFIED') CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'NONE',
  `verifiedBadge` enum('NONE','BLUE','GOLD','GREY','OFFICIAL') CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'NONE',
  `trustScore` int NOT NULL DEFAULT '0',
  `walletBalance` decimal(12,2) NOT NULL DEFAULT '0.00',
  `subscriptionPlanId` varchar(191) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `subscriptionExpiresAt` datetime(3) DEFAULT NULL,
  `bio` text CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci,
  `socialLinks` longtext CHARACTER SET utf8mb4 COLLATE utf8mb4_bin,
  `isBanned` tinyint(1) NOT NULL DEFAULT '0',
  `bannedReason` varchar(191) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `lastSeenAt` datetime(3) DEFAULT NULL,
  `createdAt` datetime(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3),
  `updatedAt` datetime(3) NOT NULL,
  `displayCurrency` varchar(191) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'USD',
  `referralCookie` varchar(191) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `countryCode` varchar(2) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `primaryIntent` enum('BUYER','SELLER','BOTH') CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `sellIntentPlatforms` longtext CHARACTER SET utf8mb4 COLLATE utf8mb4_bin,
  `sellReason` enum('NO_LONGER_NEEDED','FUNDING_NEW_PROJECT','DIVERSIFYING','OTHER') CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `onboardingCompletedAt` datetime(3) DEFAULT NULL,
  `notifPrefs` longtext CHARACTER SET utf8mb4 COLLATE utf8mb4_bin,
  `staffRoleId` varchar(191) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `expoPushToken` varchar(191) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `coverPhoto` varchar(767) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `marketingOptOut` tinyint(1) NOT NULL DEFAULT '0',
  `subscriptionCancelAtPeriodEnd` tinyint(1) NOT NULL DEFAULT '0',
  PRIMARY KEY (`id`),
  UNIQUE KEY `User_email_key` (`email`),
  UNIQUE KEY `User_username_key` (`username`),
  KEY `User_role_idx` (`role`),
  KEY `User_subscriptionPlanId_fkey` (`subscriptionPlanId`),
  KEY `User_staffRoleId_fkey` (`staffRoleId`),
  CONSTRAINT `User_staffRoleId_fkey` FOREIGN KEY (`staffRoleId`) REFERENCES `staffrole` (`id`) ON DELETE SET NULL ON UPDATE CASCADE,
  CONSTRAINT `User_subscriptionPlanId_fkey` FOREIGN KEY (`subscriptionPlanId`) REFERENCES `subscriptionplan` (`id`) ON DELETE SET NULL ON UPDATE CASCADE,
  CONSTRAINT `user_chk_1` CHECK (json_valid(`socialLinks`)),
  CONSTRAINT `user_chk_2` CHECK (json_valid(`sellIntentPlatforms`)),
  CONSTRAINT `user_chk_3` CHECK (json_valid(`notifPrefs`))
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
/*!40101 SET character_set_client = @saved_cs_client */;

